const SK='kucingku-settings-v1';let SET={lang:'ms',bk:30,unit:'auto',scheme:'sakura',mode:'system'};
const SCH={sakura:'Sakura',langit:'Langit',pudina:'Pudina',lavender:'Lavender',aprikot:'Aprikot'},MD={system:'Sistem',light:'Cerah',dark:'Gelap'};
let persistedState=JSON.stringify(S),storageReadError=false,rawStorage='';
function loadSet(){try{const r=JSON.parse(localStorage.getItem(SK)||'null');if(r&&typeof r==='object'&&r.v===1){if(r.lang==='en')SET.lang='en';if([0,14,30,60].includes(r.bk))SET.bk=r.bk;if(['auto','g','kg'].includes(r.unit))SET.unit=r.unit;if(Object.keys(SCH).includes(r.scheme))SET.scheme=r.scheme;if(Object.keys(MD).includes(r.mode))SET.mode=r.mode}}catch(e){}}
const isDark=()=>SET.mode==='dark'||(SET.mode==='system'&&typeof matchMedia==='function'&&!!matchMedia('(prefers-color-scheme: dark)').matches);
function applyTheme(){const e=document.documentElement;if(!e||!e.setAttribute)return;e.setAttribute('data-scheme',SET.scheme);e.setAttribute('data-mode',isDark()?'dark':'light');try{const m=document.querySelector('meta[name="theme-color"]');if(m&&m.setAttribute&&typeof getComputedStyle==='function'){const c=getComputedStyle(e).getPropertyValue('--bg').trim();if(c)m.setAttribute('content',c)}}catch(x){}}
function saveSet(){try{localStorage.setItem(SK,JSON.stringify({v:1,...SET}));return true}catch(e){return false}}
function save(recover=false){
try{
if(storageReadError&&!recover)throw new Error('unreadable-storage');
const json=JSON.stringify(S);localStorage.setItem(K,json);persistedState=json;storageReadError=false;return true;
}catch(e){
S=JSON.parse(persistedState);
toast(storageReadError?'Data storan tidak dapat dibaca. Export salinan asal atau import backup dahulu.':'Gagal menyimpan. Data terdahulu dikekalkan; cuba lagi atau buat backup.');
return false;
}}

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>Math.random().toString(36).slice(2,10),cat=id=>S.cats.find(c=>c.id===id);
const td=()=>new Date(Date.now()-new Date().getTimezoneOffset()*6e4).toISOString().slice(0,10);
const dd=d=>Math.round((new Date(d+'T00:00')-new Date(td()+'T00:00'))/864e5);
const fd=d=>new Date(d+'T00:00').toLocaleDateString(LOC(),{day:'numeric',month:'short',year:'numeric'});
const kgs=n=>(n/1000).toFixed(3).replace(/\.?0+$/,'')+' kg';
const fw=v=>{const n=+v,u=SET.unit;return u==='g'||(u==='auto'&&n<1000)?n+' g':kgs(n)};
const age=d=>{if(!d)return'';const n=-dd(d);if(n<0)return'';const m=mAge(d),dy=dif(addM(d,m),td());return Math.floor(n/7)+' minggu ('+(m?m+' bulan ':'')+dy+' hari)'};
