const I={plus:'<path d="M12 5v14M5 12h14"/>',phone:'<path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1 1 .4 1.9.7 2.8a2 2 0 0 1-.5 2.1L8.1 9.9a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.4c.9.3 1.8.6 2.8.7a2 2 0 0 1 1.7 2z"/>',pin:'<path d="M12 21s-7-6.1-7-11a7 7 0 0 1 14 0c0 4.9-7 11-7 11z"/><circle cx="12" cy="10" r="2.5"/>',edit:'<path d="M4 20h4L19 9a2.8 2.8 0 0 0-4-4L4 16v4z"/><path d="M13.5 6.5l4 4"/>',go:'<path d="M5 12h14M13 6l6 6-6 6"/>',doc:'<path d="M7 3h7l5 5v13H7z"/><path d="M14 3v5h5M10 13h6M10 17h4"/>',rm:'<circle cx="12" cy="12" r="9"/><path d="M14.5 9.5c-.4-.9-1.3-1.4-2.5-1.4-1.5 0-2.5.8-2.5 1.9s.9 1.6 2.5 2 2.5.9 2.5 2-1 1.9-2.5 1.9c-1.2 0-2.1-.5-2.5-1.4M12 6.5v2M12 15.5v2"/>',pal:'<path d="M12 3a9 9 0 1 0 0 18c1.1 0 1.8-.8 1.8-1.7 0-.5-.2-.9-.5-1.2-.3-.3-.5-.7-.5-1.2 0-.9.8-1.7 1.7-1.7H16a5 5 0 0 0 5-5c0-3.9-4-7.2-9-7.2z"/><circle cx="7.5" cy="11" r="1"/><circle cx="10" cy="7" r="1"/><circle cx="15" cy="7" r="1"/>',scale:'<rect x="4" y="5" width="16" height="14" rx="4"/><path d="M9 11a3 3 0 0 1 6 0M12 11l1.5-2"/>',bell:'<path d="M6 17h12l-1.5-2V11a4.5 4.5 0 0 0-9 0v4zM10 20h4"/>',db:'<ellipse cx="12" cy="6" rx="7" ry="3"/><path d="M5 6v6c0 1.7 3.1 3 7 3s7-1.3 7-3V6M5 12v6c0 1.7 3.1 3 7 3s7-1.3 7-3v-6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 8h.01"/>',set:'<path d="M4 7h10M18 7h2M4 17h2M10 17h10"/><circle cx="16" cy="7" r="2"/><circle cx="8" cy="17" r="2"/>',jd:'<rect x="4" y="5" width="16" height="15" rx="3"/><path d="M8 3v4M16 3v4M4 10h16"/>',more:'<path d="M5.5 12h.01M12 12h.01M18.5 12h.01" stroke-width="3.2"/>',vet:'<rect x="4" y="4" width="16" height="16" rx="4"/><path d="M12 8v8M8 12h8"/>',home:'<path d="M3 11l9-8 9 8v9a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/>',cats:'<circle cx="6.5" cy="10" r="1.8"/><circle cx="10" cy="5.5" r="1.8"/><circle cx="14" cy="5.5" r="1.8"/><circle cx="17.5" cy="10" r="1.8"/><path d="M12 11c-3 0-5.5 3-5.5 5.5 0 2 1.7 2.5 3 2.5 1 0 1.5-.5 2.5-.5s1.5.5 2.5.5c1.3 0 3-.5 3-2.5 0-2.5-2.5-5.5-5.5-5.5z"/>',bk:'<path d="M12 4v11m0 0l-4-4m4 4l4-4M5 20h14"/>',chat:'<path d="M5 5h14a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2h-8l-5 4v-4H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2z"/><path d="M8 10h8M8 13h5"/>'};
function toast(m){const t=$('#t');t.textContent=trs(m);t.hidden=false;clearTimeout(toast.h);toast.h=setTimeout(()=>t.hidden=true,2400)}
const GP=c=>c.sex==='Jantan'?{bg:'#DCEBFF',ear:'#BBD4F5',inn:'#E3EEFC',bl:'#9CC2F5',no:'#7FA6DA',pt:'#C9DDF7',ln:'#6F9BD6'}:{bg:'#FFE3EA',ear:'#F7C6D0',inn:'#FBE1E7',bl:'#F9B8C6',no:'#E98AA0',pt:'#F5C9A5',ln:'#E27C97'};
const face=c=>{const g=GP(c);return `<svg viewBox="0 0 120 120" role="img" aria-label="${esc(c.name)}"><rect width="120" height="120" fill="${g.bg}"/><path d="M22 62 18 24 46 42ZM98 62 102 24 74 42Z" fill="${g.ear}"/><path d="M26 56 24 34 40 44ZM94 56 96 34 80 44Z" fill="${g.inn}"/><ellipse cx="60" cy="78" rx="46" ry="38" fill="#FFF6EC"/><ellipse cx="38" cy="60" rx="13" ry="9" fill="${g.pt}" opacity=".85"/><circle cx="43" cy="76" r="5" fill="#5A4558"/><circle cx="77" cy="76" r="5" fill="#5A4558"/><circle cx="45" cy="74" r="1.6" fill="#fff"/><circle cx="79" cy="74" r="1.6" fill="#fff"/><ellipse cx="32" cy="88" rx="8" ry="5" fill="${g.bl}" opacity=".7"/><ellipse cx="88" cy="88" rx="8" ry="5" fill="${g.bl}" opacity=".7"/><path d="M55 86q5 5 10 0" stroke="#5A4558" stroke-width="2.4" fill="none" stroke-linecap="round"/><path d="M60 82l-3-2h6z" fill="${g.no}"/></svg>`};
function av(c){return `<span class="av ${c.sex==='Jantan'?'j':'b'}">${c.photo?`<img src="${c.photo}" alt="${esc(c.name)}">`:face(c)}</span>`}
const lastW=id=>S.recs.filter(r=>r.cat===id&&r.type==='berat'&&r.date<=td()).sort((a,b)=>b.date.localeCompare(a.date))[0];
function tasks(){const o=[],T0=td();S.cats.forEach(c=>{const p=plan(c);if(!p)return;[['berat',p.t],['vaksin',p.v],['cacing',p.w]].forEach(([t,x])=>{const d=dif(T0,x.d);if(d<=30)o.push({c,t,l:x.l,date:x.d,d})})});S.recs.forEach(r=>{if(r.type!=='lawatan')return;const c=cat(r.cat),d=dif(T0,r.date);if(c&&d>=0&&d<=30)o.push({c,t:'lawatan',l:r.name+(r.time?' · '+r.time:''),date:r.date,d})});return o.sort((a,b)=>a.d-b.d)}
const VER='1.8.1';
// Borang maklum balas Google Forms. form: pautan .../viewform (atau forms.gle). ver: ID medan versi app untuk diisi automatik, cth. 'entry.123456789' (pilihan).
const FB={form:'https://docs.google.com/forms/d/e/1FAIpQLSfK5e5iSrBBUDWH5bMCLIxYPe6dWAKIaNkdOt_UXYqnKObJyw/viewform',ver:'entry.103926294'};
function fbUrl(){const f=String(FB.form||'').trim();if(!/^https:\/\/(docs\.google\.com\/forms\/d\/e\/[\w-]+\/viewform|forms\.gle\/[\w-]+)(\?[^\s"'<>]*)?$/.test(f))return '';if(!/^entry\.\d+$/.test(FB.ver)||!f.startsWith('https://docs.google.com/'))return f;return f+(f.includes('?')?'&':'?')+'usp=pp_url&'+FB.ver+'='+encodeURIComponent(`Kucingku v${VER} · ${SET.lang==='en'?'EN':'BM'}`)}
const TL={vaksin:'Vaksin core',cacing:'Ubat cacing',berat:'Timbang berat',lawatan:'Temujanji vet'};
const rel=d=>d<0?'Lewat '+-d+' hari':d===0?'Hari ini':d===1?'Esok':d+' hari lagi';
const trow=({c,t,l,date,d})=>`<button class="row" data-action="task" data-id="${c.id}" data-type="${t}">${av(c)}<span><b>${TL[t]} ${esc(c.name)}</b><span class="mute">${esc(l)} · ${t==='lawatan'?'':'±'}${fd(date)}</span></span><span class="pill ${d<0?'bad':''}">${rel(d)}</span></button>`;
function jdv(){const k=tasks(),G=[['Lewat',x=>x.d<0],['Hari ini',x=>x.d===0],['7 hari akan datang',x=>x.d>0&&x.d<=7],['8 hingga 30 hari',x=>x.d>7]];
const em=m=>`<div class="ok">${ZZ}<p class="mute">${m}</p></div>`;
return `<h2 style="margin-top:12px">Jadual</h2><p class="mute">Rawatan, timbang dan temujanji dalam 30 hari akan datang.</p>`+(S.cats.length?(G.map(([t,f])=>{const l=k.filter(f);return l.length?`<h3 class="gh">${t}</h3>`+l.map(trow).join(''):''}).join('')||em('Tiada apa-apa dalam 30 hari akan datang.')):em('Tambah kucing untuk melihat jadual.'))}
// ---- Perbelanjaan
let expP='bulan';
const EP={bulan:'Bulan ini',tahun:'Tahun ini',semua:'Semua'};
const money=n=>'RM '+n.toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2});
const costs=()=>{const T0=td();return S.recs.filter(r=>r.type!=='berat'&&r.cost>0&&r.date<=T0&&cat(r.cat))};
const rsum=a=>Math.round(a.reduce((x,r)=>x+r.cost,0)*100)/100;
const ymKey=(y,m)=>y+'-'+String(m).padStart(2,'0');
const inP=(r,p)=>{const n=p==='tahun'?4:7;return p==='semua'||r.date.slice(0,n)===td().slice(0,n)};
const prevP=p=>{const T0=td(),y=+T0.slice(0,4),m=+T0.slice(5,7);return p==='tahun'?r=>r.date.slice(0,4)===String(y-1):p==='bulan'?r=>r.date.slice(0,7)===(m===1?ymKey(y-1,12):ymKey(y,m-1)):null};
const months6=()=>{const T0=td();let y=+T0.slice(0,4),m=+T0.slice(5,7);const o=[];for(let i=0;i<6;i++){o.unshift({k:ymKey(y,m),l:new Date(y,m-1,1).toLocaleDateString(LOC(),{month:'short'})});m--;if(m<1){m=12;y--}}return o};
const monthCost=()=>rsum(costs().filter(r=>inP(r,'bulan')));
function expv(){const H=`<button class="bk" data-action="go" data-view="more">‹ Lagi</button><h2 style="margin-top:12px">Perbelanjaan</h2>`,all=costs();
if(!all.length)return H+`<div class="ok">${ZZ}<p class="mute">Belum ada kos direkodkan. Isi Kos (RM) semasa menambah rekod vaksin, ubat cacing atau lawatan vet.</p></div>`;
const a=all.filter(r=>inP(r,expP)),tot=rsum(a),pf=prevP(expP),pv=pf?rsum(all.filter(pf)):null;
let h=H+`<div class="seg" style="margin:0 0 12px">${Object.keys(EP).map(k=>`<button class="${expP===k?'on':''}" data-action="expP" data-v="${k}">${EP[k]}</button>`).join('')}</div>`;
h+=`<div class="card ehero"><span class="mute">Jumlah</span><div class="en">${money(tot)}</div><p class="mute">${trs(a.length+' rekod')}${pv!==null?' · '+trs(expP==='bulan'?'Bulan lalu':'Tahun lalu')+' '+money(pv):''}</p></div>`;
const M=months6(),vals=M.map(m=>rsum(all.filter(r=>r.date.slice(0,7)===m.k))),mx=Math.max(...vals,1),cur=td().slice(0,7);
h+=`<div class="card"><b>6 bulan terakhir</b><p class="mute">Jumlah sebulan (RM)</p><div class="eb">${M.map((m,i)=>`<div class="ec${m.k===cur?' on':''}"><small>${vals[i]?Math.round(vals[i]):''}</small><i style="height:${vals[i]?Math.max(4,Math.round(vals[i]/mx*80)):0}px"></i><span>${m.l}</span></div>`).join('')}</div></div>`;
if(!a.length)return h+`<div class="card"><p class="mute">Tiada kos dalam tempoh ini.</p></div>`;
const bar=(items)=>{const mv=Math.max(...items.map(x=>x[1]));return items.map(([l,v,pre])=>`<div class="er"><div class="eh">${pre||''}<span>${l}</span><b>${money(Math.round(v*100)/100)}</b></div><div class="prog"><i style="width:${Math.max(3,Math.round(v/mv*100))}%"></i></div></div>`).join('')};
const bt={};a.forEach(r=>{bt[r.type]=(bt[r.type]||0)+r.cost});
h+=`<div class="card"><b>Mengikut jenis</b>${bar(Object.entries(bt).sort((x,y)=>y[1]-x[1]).map(([k,v])=>[T[k],v]))}</div>`;
const bc=S.cats.map(c=>[esc(c.name),rsum(a.filter(r=>r.cat===c.id)),av(c)]).filter(x=>x[1]>0).sort((x,y)=>y[1]-x[1]);
if(S.cats.length>1)h+=`<div class="card"><b>Mengikut kucing</b>${bar(bc)}</div>`;
h+=`<h2>Terkini</h2>`+a.slice().sort((x,y)=>y.date.localeCompare(x.date)).slice(0,5).map(r=>{const c=cat(r.cat);return `<div class="row">${av(c)}<span><b>${esc(r.name||T[r.type])}</b><span class="mute">${fd(r.date)} · ${esc(c.name)}</span></span><span class="pill">${money(r.cost)}</span></div>`}).join('');
return h+`<p class="mute" style="text-align:center;margin-top:14px">Temujanji akan datang tidak dikira.</p>`}
// ---- Kalendar (.ics)
let calO={a:true,t:true};
const icsEsc=x=>String(x).replace(/\\/g,'\\\\').replace(/;/g,'\;').replace(/,/g,'\\,').replace(/\r?\n/g,'\\n');
const ub=ch=>{const c=ch.codePointAt(0);return c<128?1:c<2048?2:c<65536?3:4};
const icsFold=l=>{let o='',n=0;for(const ch of l){const b=ub(ch);if(n+b>73){o+='\r\n ';n=1}o+=ch;n+=b}return o};
const d8=d=>d.replace(/-/g,'');
const stamp=()=>new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+/,'');
const p2=n=>String(n).padStart(2,'0');
function vevent(e){const L=['BEGIN:VEVENT','UID:'+e.uid,'DTSTAMP:'+stamp()];
if(e.time){const y=+e.date.slice(0,4),mo=+e.date.slice(5,7),da=+e.date.slice(8,10),H=+e.time.slice(0,2),Mi=+e.time.slice(3,5),z=new Date(Date.UTC(y,mo-1,da,H,Mi)+36e5);
L.push('DTSTART:'+d8(e.date)+'T'+p2(H)+p2(Mi)+'00','DTEND:'+z.getUTCFullYear()+p2(z.getUTCMonth()+1)+p2(z.getUTCDate())+'T'+p2(z.getUTCHours())+p2(z.getUTCMinutes())+'00')}
else L.push('DTSTART;VALUE=DATE:'+d8(e.date),'DTEND;VALUE=DATE:'+d8(addD(e.date,1)));
L.push('SUMMARY:'+icsEsc(e.title));if(e.loc)L.push('LOCATION:'+icsEsc(e.loc));if(e.desc)L.push('DESCRIPTION:'+icsEsc(e.desc));
L.push('TRANSP:'+(e.time?'OPAQUE':'TRANSPARENT'));
(e.alarms||[]).forEach(a=>L.push('BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:'+icsEsc(e.title),'TRIGGER:'+a,'END:VALARM'));
L.push('END:VEVENT');return L}
const icsText=ev=>['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Kucingku//BM//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH','X-WR-CALNAME:Kucingku',...ev.flatMap(vevent),'END:VCALENDAR'].map(icsFold).join('\r\n')+'\r\n';
function apptEv(r){const c=cat(r.cat),v=S.vets.find(x=>x.id===r.clinic),tm=/^\d{2}:\d{2}$/.test(r.time||'')?r.time:'';
return{uid:r.id+'@kucingku',date:r.date,time:tm,title:'Vet: '+r.name+' ('+c.name+')',loc:v?[v.name,v.addr&&!/^https?:/i.test(v.addr)?v.addr:''].filter(Boolean).join(', '):'',desc:[c.name,v&&v.tel?v.name+' '+v.tel:'',r.note].filter(Boolean).join('\n'),alarms:tm?['-P1D','-PT1H']:['-PT15H','PT8H']}}
function calEvents(o){const T0=td(),out=[];
if(o.a)S.recs.filter(r=>r.type==='lawatan'&&r.date>=T0&&cat(r.cat)).sort((x,y)=>(x.date+(x.time||'')).localeCompare(y.date+(y.time||''))).forEach(r=>out.push(apptEv(r)));
if(o.t)S.cats.forEach(c=>{const p=plan(c);if(!p)return;const note=trs('Anggaran. Sahkan dengan doktor haiwan anda.'),add=(t,x,l)=>out.push({uid:c.id+'-'+t+'@kucingku',date:x.d<T0?T0:x.d,title:trs(l)+' · '+c.name,desc:trs(x.l)+'. '+note,alarms:['PT9H']});
add('vaksin',p.v,'Vaksin core');add('cacing',p.w,'Ubat cacing');if(!p.rb)add('rabies',{d:p.rbd,l:'Cadangan'},'Vaksin rabies')});
return out}
async function icsSave(ev,name){if(!ev.length){toast('Tiada acara akan datang untuk di-export');return}
try{const dl=await getDl();if(!dl){toast('Export tidak tersedia di sini');return}
const data=new Blob([icsText(ev)],{type:'text/calendar;charset=utf-8'});
try{await dl.save({filename:name,data})}catch(e){if(e&&e.code==='rejected_extension')await dl.save({filename:name+'.txt',data});else throw e}
toast('Muat turun kalendar dimulakan')}catch(e){if(e&&e.code==='declined')return;toast('Export kalendar gagal')}}
const calExp=()=>icsSave(calEvents(calO),'kucingku-kalendar-'+td()+'.ics');
function calOne(id){const r=S.recs.find(x=>x.id===id&&x.type==='lawatan'&&cat(x.cat));if(r)icsSave([apptEv(r)],'kucingku-temujanji-'+r.date+'.ics')}
function calTog(k){if(k!=='a'&&k!=='t')return;calO[k]=!calO[k];render()}
function calv(){const n=calEvents({a:true}).length,m=calEvents({t:true}).length,tg=(k,t,c)=>`<button class="row tg${calO[k]?' on':''}" data-action="calTog" data-v="${k}" aria-pressed="${!!calO[k]}"><span class="cb">${calO[k]?'✓':''}</span><span><b>${t}</b><span class="mute">${trs(c+' acara')}</span></span></button>`;
return `<button class="bk" data-action="go" data-view="more">‹ Lagi</button><h2 style="margin-top:12px">Kalendar</h2>${tg('a','Temujanji vet',n)}${tg('t','Vaksin dan ubat cacing',m)}<button class="btn" data-action="calExp" style="margin-top:12px">Export kalendar (.ics)</button><p class="mute" style="margin-top:12px">Salinan semasa. Export semula selepas ada perubahan; acara yang sama akan dikemas kini.</p>`}
function morev(){const m=(v,i,t,s)=>`<button class="row mr" data-action="go" data-view="${v}"><svg viewBox="0 0 24 24" aria-hidden="true">${I[i]}</svg><span><b>${t}</b><span class="mute">${s}</span></span><span class="chev">›</span></button>`;
return `<h2 style="margin-top:12px">Lagi</h2>`+ixRow()+m('vet','vet','Vet',S.vets.length?S.vets.length+' klinik disimpan':'Simpan klinik dan nombor telefon')+m('exp','rm','Perbelanjaan',monthCost()?trs('Bulan ini')+' '+money(monthCost()):'Belum ada kos direkodkan')+m('cal','jd','Kalendar','Temujanji dan jadual rawatan')+m('set','set','Setting','Bahasa, unit, peringatan dan data')+`<p class="mute" style="text-align:center;margin-top:26px">Kucingku v${VER}</p>`}
const vlink=v=>{try{const u=new URL(v.addr);if(/^https?:$/.test(u.protocol))return u.href}catch(e){}return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent((v.name+' '+v.addr).trim())};
const vn=r=>{const v=S.vets.find(x=>x.id===r.clinic);return v?' · '+esc(v.name):''};
function vetv(){const V=S.vets.slice().sort((a,b)=>b.main-a.main||a.name.localeCompare(b.name));
return `<button class="bk" data-action="go" data-view="more">‹ Lagi</button><div class="kh"><h2>Vet</h2><button class="btn" style="margin:0;padding:10px 18px" data-action="vetForm">+ Tambah</button></div>`+(V.length?V.map(v=>`<div class="card vc"><div class="vh"><b class="kn">${esc(v.name)}</b><span class="chips">${v.main?'<span class="chip">Klinik utama</span>':''}${v.h24?'<span class="chip">24 jam</span>':''}</span></div>${v.doc?`<p class="mute">${esc(v.doc)}</p>`:''}${v.hours?`<p>${esc(v.hours)}</p>`:''}${v.addr&&!/^https?:/i.test(v.addr)?`<p>${esc(v.addr)}</p>`:''}${v.note?`<p class="mute">${esc(v.note)}</p>`:''}<div class="acts">${v.tel?`<a class="btn ic" href="tel:${esc(v.tel.replace(/\s/g,''))}"><svg viewBox="0 0 24 24" aria-hidden="true">${I.phone}</svg>Telefon</a>`:''}<a class="btn g ic" href="${esc(vlink(v))}" target="_blank" rel="noopener"><svg viewBox="0 0 24 24" aria-hidden="true">${I.pin}</svg>Peta</a><button class="btn g ic" data-action="vetForm" data-id="${v.id}"><svg viewBox="0 0 24 24" aria-hidden="true">${I.edit}</svg>Edit</button></div></div>`).join(''):`<div class="ok">${ZZ}<p class="mute">Belum ada klinik. Tambah klinik yang anda gunakan supaya nombor telefonnya sentiasa dekat.</p></div>`)}
function vetForm(id){const v=id?S.vets.find(x=>x.id===id):{};
sheet(`<h2>${id?'Edit klinik':'Tambah klinik'}</h2><form data-submit="vet" data-id="${id||''}">${L('Nama klinik',`<input name="name" required value="${esc(v.name)}">`)}${L('Telefon',`<input name="tel" type="tel" inputmode="tel" value="${esc(v.tel)}" placeholder="cth. 03-1234 5678">`)}${L('Alamat atau pautan peta',`<input name="addr" value="${esc(v.addr)}" placeholder="Alamat, atau tampal pautan Google Maps">`)}${L('Waktu operasi',`<input name="hours" value="${esc(v.hours)}" placeholder="cth. Isnin hingga Sabtu, 9 pagi hingga 8 malam">`)}${L('Nama doktor',`<input name="doc" value="${esc(v.doc)}">`)}${L('Catatan',`<input name="note" value="${esc(v.note)}">`)}<label class="ck"><input type="checkbox" name="main"${v.main?' checked':''}> Klinik utama</label><label class="ck"><input type="checkbox" name="h24"${v.h24?' checked':''}> Buka 24 jam</label><button class="btn">Simpan</button>${id?`<button type="button" class="btn r" data-action="delVet" data-id="${id}">Padam klinik ini</button>`:''}</form>`)}
function saveVet(e,id){e.preventDefault();const o=Object.fromEntries(new FormData(e.target));if(!(o.name||'').trim()){toast('Masukkan nama klinik');return}o.main=!!o.main;o.h24=!!o.h24;o.tel=(o.tel||'').replace(/[^\d+\-\s()]/g,'');if(!id&&!S.vets.length)o.main=true;if(o.main)S.vets.forEach(x=>x.main=false);
if(id)Object.assign(S.vets.find(x=>x.id===id),o);else S.vets.push({id:uid(),...o});if(!save())return;closeSh();render();toast('Klinik disimpan')}
function delVet(id){ask('Padam klinik ini?','Padam',()=>{S.vets=S.vets.filter(v=>v.id!==id);S.recs.forEach(r=>{if(r.clinic===id)delete r.clinic});if(!save()){render();return}render();toast('Klinik dipadam')})}
const clinicSel=r=>S.vets.length?L('Klinik',`<select name="clinic"><option value="">-</option>${S.vets.slice().sort((a,b)=>b.main-a.main).map(v=>`<option value="${v.id}"${(r.clinic||(!r.id&&v.main?v.id:''))===v.id?' selected':''}>${esc(v.name)}</option>`).join('')}</select>`):'';
const costIn=r=>L('Kos (RM)',`<input name="cost" type="number" inputmode="decimal" step="0.01" min="0" placeholder="Pilihan" value="${r.cost||''}">`);
